package com.rpsbattle.tournament;
import com.rpsbattle.tournament.domain.*;
import com.rpsbattle.tournament.scheduler.*;
import com.rpsbattle.tournament.persistence.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class GroupKnockoutTest {
 @Test void noEligibleParticipantsCreateNoFakeFinalRoomOrChampion(){var t=cup(4,1);for(var p:t.participants)t.operations=t.operations.participant(p.participantId(),ParticipantStatus.DISQUALIFIED);TournamentAdministrationService.settleForfeits(t);assertThat(GroupKnockoutScheduler.qualify(t)).isTrue();assertThat(GroupKnockoutScheduler.complete(t)).isTrue();assertThat(t.bracket.getLast().winnerParticipantId()).isNull();assertThat(t.matches).hasSize(2);assertThat(GroupKnockoutScheduler.view(t)).allSatisfy(row->assertThat((List<?>)row.get("qualified")).isEmpty());}
 Tournament cup(int count,int bestOf){var t=new Tournament(UUID.randomUUID().toString(),"Groups",TournamentFormat.GROUP_KNOCKOUT,Instant.now());t.bestOf=bestOf;t.status=TournamentStatus.RUNNING;for(int i=0;i<count;i++)t.participants.add(new TournamentParticipant(UUID.randomUUID().toString(),null,"","P"+i,i,null,null,i+1,null));t.matches.addAll(new FormatTournamentScheduler().schedule(t));return t;}
 void finish(TournamentMatch m){TournamentFixtures.finish(m,m.participantA.participantId(),8,1);}
 void groups(Tournament t){for(int i=0;i<t.bestOf/2+1;i++){t.matches.stream().filter(m->m.status==TournamentMatch.Status.PENDING).forEach(this::finish);TournamentSeries.advance(t);}}
 @Test void seededGroupsAreBalancedDeterministicAndNeverCrossPair(){for(int n:List.of(4,5,6,9,32)){var t=cup(n,1);assertThat(t.groupStage.groups().get("A").size()-t.groupStage.groups().get("B").size()).isBetween(-1,1);assertThat(t.matches).allMatch(m->t.groupStage.groups().get(GroupKnockoutScheduler.group(t,m)).containsAll(List.of(m.participantA.participantId(),m.participantB.participantId())));int a=t.groupStage.groups().get("A").size(),b=t.groupStage.groups().get("B").size();assertThat(t.matches).hasSize(a*(a-1)/2+b*(b-1)/2);var ids=t.matches.stream().map(m->m.id).toList();assertThat(new GroupKnockoutScheduler().schedule(t).stream().map(m->m.id).toList()).isEqualTo(ids);assertThat(t.bracket).isEmpty();}assertThatThrownBy(()->cup(3,1)).hasMessage("GROUP_STAGE_REQUIRES_FOUR_PARTICIPANTS");}
 @Test void qualificationWaitsForEverySeriesAndReviewThenCrossSeedsOnlyOnce(){var t=cup(6,3);t.matches.forEach(this::finish);assertThat(GroupKnockoutScheduler.qualify(t)).isFalse();TournamentSeries.advance(t);t.matches.stream().filter(m->m.status==TournamentMatch.Status.PENDING).forEach(this::finish);var root=t.matches.getFirst();t.operations=t.operations.review(root.id,"review");assertThat(GroupKnockoutScheduler.qualify(t)).isFalse();t.operations=t.operations.review(root.id,null);t.status=TournamentStatus.PAUSED;assertThat(GroupKnockoutScheduler.qualify(t)).isFalse();t.status=TournamentStatus.RUNNING;var a=GroupKnockoutScheduler.standings(t,"A");var b=GroupKnockoutScheduler.standings(t,"B");assertThat(GroupKnockoutScheduler.qualify(t)).isTrue();assertThat(t.groupStage.qualifiers()).containsExactly(a.get(0).participantId(),b.get(0).participantId(),a.get(1).participantId(),b.get(1).participantId());assertThat(t.bracket.getFirst().slotA()).isEqualTo(a.getFirst().participantId());assertThat(t.bracket.getFirst().slotB()).isEqualTo(b.get(1).participantId());int size=t.matches.size();assertThat(GroupKnockoutScheduler.qualify(t)).isFalse();assertThat(t.matches).hasSize(size);assertThat(t.operations.audit().stream().filter(e->e.type().equals("GROUP_QUALIFICATION_LOCKED"))).hasSize(1);}
 @Test void knockoutRematchKeepsGroupStandingsAndFinalDeterminesChampionOrder(){var t=cup(4,1);groups(t);var before=GroupKnockoutScheduler.view(t);assertThat(GroupKnockoutScheduler.qualify(t)).isTrue();var semis=t.matches.stream().filter(m->m.round>t.groupStage.rounds()).toList();assertThat(semis).hasSize(2);String group="A";for(var m:semis)TournamentFixtures.finish(m,t.groupStage.groups().get(group).contains(m.participantA.participantId())?m.participantA.participantId():m.participantB.participantId(),4,4);t.matches.addAll(SingleEliminationScheduler.advance(t));var last=t.matches.getLast();assertThat(t.groupStage.groups().get(group)).contains(last.participantA.participantId(),last.participantB.participantId());finish(last);t.matches.addAll(SingleEliminationScheduler.advance(t));assertThat(GroupKnockoutScheduler.complete(t)).isTrue();assertThat(t.bracket.getLast().winnerParticipantId()).isEqualTo(last.winnerParticipantId);assertThat(GroupKnockoutScheduler.standings(t,"A")).isEqualTo(before.getFirst().get("ranking"));assertThat(new com.rpsbattle.tournament.ranking.RankingService(new com.rpsbattle.tournament.ranking.ClassicScoringRule()).rank(t).getFirst().participantId()).isEqualTo(last.winnerParticipantId);}
 @Test void inactiveQualifiersBecomeByesAndSnapshotSurvivesJsonRestore(){var t=cup(4,1);groups(t);var removed=t.groupStage.groups().get("A").getFirst();t.operations=t.operations.participant(removed,ParticipantStatus.WITHDRAWN);assertThat(GroupKnockoutScheduler.qualify(t)).isTrue();assertThat(t.groupStage.qualifiers()).doesNotContain(removed).containsNull();var converter=new TournamentDetailsConverter();var saved=converter.convertToEntityAttribute(converter.convertToDatabaseColumn(TournamentDetails.snapshot(t)));var restored=new Tournament(t.id,t.name,t.format,t.createdAt);restored.participants.addAll(t.participants);t.matches.forEach(m->restored.matches.add(m.copy()));saved.restore(restored);restored.status=TournamentStatus.RUNNING;assertThat(restored.groupStage).isEqualTo(t.groupStage);assertThat(restored.bracket).isEqualTo(t.bracket);assertThat(GroupKnockoutScheduler.qualify(restored)).isFalse();assertThat(SingleEliminationScheduler.advance(restored)).isEmpty();}
 @Test void failuresAndUnfinishedGamesCannotCreateKnockout(){var t=cup(5,1);assertThat(GroupKnockoutScheduler.complete(t)).isFalse();groups(t);t.matches.getFirst().status=TournamentMatch.Status.FAILED;assertThat(GroupKnockoutScheduler.qualify(t)).isFalse();assertThat(t.groupStage.locked()).isFalse();assertThat(t.bracket).isEmpty();}
}
